import type {
  JsonPlaceholderComment,
  JsonPlaceholderPost,
} from '@/types/jsonplaceholder'

const BASE = 'https://jsonplaceholder.typicode.com'

export async function fetchRecentPosts(
  limit: number
): Promise<JsonPlaceholderPost[]> {
  const res = await fetch(`${BASE}/posts?_limit=${limit}`, {
    cache: 'no-store',
  })
  if (!res.ok) {
    throw new Error(`Failed to fetch posts: ${res.status}`)
  }
  return res.json() as Promise<JsonPlaceholderPost[]>
}

export async function fetchAllPosts(): Promise<JsonPlaceholderPost[]> {
  const res = await fetch(`${BASE}/posts`, {
    next: { revalidate: 60 },
  })
  if (!res.ok) {
    throw new Error(`Failed to fetch posts: ${res.status}`)
  }
  return res.json() as Promise<JsonPlaceholderPost[]>
}

export async function fetchPostById(
  id: string
): Promise<JsonPlaceholderPost | null> {
  const res = await fetch(`${BASE}/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) {
    return null
  }
  const data = (await res.json()) as JsonPlaceholderPost
  if (typeof data.id !== 'number') {
    return null
  }
  return data
}

export async function fetchCommentsForPost(
  id: string
): Promise<JsonPlaceholderComment[]> {
  const res = await fetch(`${BASE}/posts/${id}/comments`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) {
    throw new Error(`Failed to fetch comments: ${res.status}`)
  }
  return res.json() as Promise<JsonPlaceholderComment[]>
}

export async function fetchPostsForStaticPaths(
  slice: number
): Promise<{ id: string }[]> {
  const res = await fetch(`${BASE}/posts`, { cache: 'no-store' })
  if (!res.ok) {
    throw new Error(`Failed to fetch posts: ${res.status}`)
  }
  const posts = (await res.json()) as JsonPlaceholderPost[]
  return posts.slice(0, slice).map((post) => ({ id: String(post.id) }))
}

