import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import {
  fetchCommentsForPost,
  fetchPostById,
  fetchPostsForStaticPaths,
} from '@/lib/jsonplaceholder'
import type { JsonPlaceholderComment } from '@/types/jsonplaceholder'
import type { JsonPlaceholderPost } from '@/types/jsonplaceholder'

export const revalidate = 300

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  return fetchPostsForStaticPaths(10)
}

async function getPostData(id: string): Promise<{
  post: JsonPlaceholderPost
  comments: JsonPlaceholderComment[]
} | null> {
  const [post, comments] = await Promise.all([
    fetchPostById(id),
    fetchCommentsForPost(id).catch(() => [] as JsonPlaceholderComment[]),
  ])

  if (!post) {
    return null
  }

  return { post, comments }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const result = await getPostData(id)

  if (!result) {
    return { title: 'Post' }
  }

  const { post } = result
  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const result = await getPostData(id)

  if (!result) {
    notFound()
  }

  const { post, comments } = result

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

