import { NextResponse } from 'next/server'
import type { LocalApiPost } from '@/types/api'

type UpdatePostBody = {
  title?: unknown
  content?: unknown
}

type RouteContext = {
  params: Promise<{ id: string }>
}

function parseId(id: string): number | null {
  const n = Number.parseInt(id, 10)
  return Number.isFinite(n) ? n : null
}

export async function GET(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<LocalApiPost | { error: string }>> {
  const { id: idParam } = await context.params
  const id = parseId(idParam)
  if (id === null) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 })
  }

  const post: LocalApiPost = {
    id,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: Request,
  context: RouteContext
): Promise<NextResponse<LocalApiPost | { error: string }>> {
  const { id: idParam } = await context.params
  const id = parseId(idParam)
  if (id === null) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 })
  }

  let body: UpdatePostBody
  try {
    body = (await request.json()) as UpdatePostBody
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    )
  }

  const title = typeof body.title === 'string' ? body.title : undefined
  const content = typeof body.content === 'string' ? body.content : undefined

  const updatedPost: LocalApiPost = {
    id,
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<{ message: string } | { error: string }>> {
  const { id: idParam } = await context.params
  const id = parseId(idParam)
  if (id === null) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 })
  }

  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

